<script setup lang="ts">import {Link,router} from '@inertiajs/vue3';import {ref} from 'vue';import AdminLayout from '@/Layouts/AdminLayout.vue';import PageMeta from '@/Components/PageMeta.vue';import EmptyState from '@/Components/EmptyState.vue';import Pagination from '@/Components/Pagination.vue';import type {Paginated,PdfTemplate} from '@/types';defineProps<{templates:Paginated<PdfTemplate>}>();const selected=ref<PdfTemplate|null>(null);const activate=(item:PdfTemplate)=>router.patch(route('admin.templates.activation',item.id),{active:!item.is_active},{preserveScroll:true});</script>
<template><AdminLayout title="Plantillas PDF" eyebrow="Configuración documental"><PageMeta title="Plantillas PDF" noindex/><section class="admin-content"><div class="content-toolbar"><div><p class="kicker">Calibración</p><h2>{{ templates.total }} plantillas</h2></div><Link class="button button--admin" :href="route('admin.templates.create')">+ Nueva plantilla</Link></div><div class="template-layout"><div class="panel table-panel"><div v-if="templates.data.length" class="template-list"><div v-for="item in templates.data" :key="item.id" :class="['template-row',{active:selected?.id===item.id}]"><button type="button" @click="selected=item"><span class="file-icon">PDF</span><span><strong>{{ item.name }}</strong><small>{{ item.document_type||'Cualquier tipo' }} · {{ item.page_size||'Sin tamaño' }} · QR pág. {{ item.qr_page }}</small></span><i :class="item.is_active?'on':'off'">{{ item.is_active?'Activa':'Inactiva' }}</i></button><div class="row-actions"><Link class="row-action" :href="route('admin.templates.edit',item.id)">Calibrar</Link><button class="row-action" type="button" @click="activate(item)">{{ item.is_active?'Desactivar':'Activar' }}</button></div></div></div><EmptyState v-else title="No hay plantillas configuradas"/><Pagination :links="templates.links"/></div><aside class="panel calibration"><p class="kicker">Coordenadas registradas</p><h2>{{ selected?.name||'Seleccione una plantilla' }}</h2><template v-if="selected"><p>Página {{ selected.qr_page }} · X {{ selected.qr_x }} · Y {{ selected.qr_y }} · {{ selected.qr_width }} × {{ selected.qr_height }} mm</p><Link class="button button--outline-small" :href="route('admin.templates.edit',selected.id)">Editar calibración</Link></template><p v-else>Seleccione una fila para consultar su calibración QR.</p></aside></div></section></AdminLayout></template>
